// Base class must have a virtual destructor for polymorphic deletion
class Investment {
public:
    virtual ~Investment() = default; // CRITICAL!
    // ... interface
};

class Stock : public Investment { /* ... */ };
class Bond : public Investment { /* ... */ };

// Custom deleter can be used for logging or other cleanup actions
auto loggingDeleter = [](Investment* inv) {
    // log("Deleting investment...");
    delete inv;
};

// A factory function returning a unique pointer with a custom deleter.
// Uses perfect forwarding to pass arguments to the concrete constructor.
template<typename... Ts>
auto makeInvestment(const std::string& type, Ts&&... params)
{
    // Create a unique_ptr with the custom deleter type.
    std::unique_ptr<Investment, decltype(loggingDeleter)> pInvestment(nullptr, loggingDeleter);

    if (type == "stock") {
        pInvestment.reset(new Stock(std::forward<Ts>(params)...));
    } else if (type == "bond") {
        pInvestment.reset(new Bond(std::forward<Ts>(params)...));
    }
    // Returns by value, but move semantics transfer ownership efficiently.
    return pInvestment;
}

// Client code is decoupled from concrete types.
void clientCode() {
    auto stock = makeInvestment("stock", /* ticker, etc. */);
    // ... use the investment via its base class interface
} // `stock` is automatically destroyed and logged via the custom deleter here.
